function installVisualTheme(){if(!document?.head||document.getElementById?.('ruta-visual-v1'))return false;let style=E('style');style.id='ruta-visual-v1';style.textContent=VISUAL_CSS;document.head.append(style);return true}
const coverageLabel=status=>status==='MASTERED'?'EVIDENCIA_INICIAL_SUFICIENTE':status;
const g=()=>store.goals.find(x=>x.id===store.active);
