const flushSave=()=>persistQueue;
function note(s,bad=false){statusEl.textContent=s;statusEl.className=bad?'err':'ok';statusEl.setAttribute?.('aria-live',bad?'assertive':'polite')}
async function api(route,payload={}){let c=new AbortController(),timer=setTimeout(()=>c.abort(),100000),body={...payload};if(activeProfile?.profile_id&&!body.profile_id)body.profile_id=activeProfile.profile_id;try{let r=await fetch(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal});let d=await r.json();if(!r.ok)throw Error(d.error||'Error del servidor');return d}catch(e){if(e.name==='AbortError')throw Error('La solicitud tardó demasiado; revisa el servidor antes de repetir.');if(e instanceof TypeError)throw Error('No se pudo contactar al servidor local.');throw e}finally{clearTimeout(timer)}}
async function task(label,fn){if(busy)return;busy=true;note(label);try{await fn();if(statusEl.textContent===label&&!persistenceDirty&&pendingWrites===0)note('Listo.')}catch(e){note(e?.message||String(e),true);console.error(e)}finally{busy=false}}
function nav(){let bar=E('nav'),brand=E('div','Ruta');bar.className='app-nav';brand.className='nav-brand';bar.ariaLabel='Navegación principal';bar.append(brand);let add=(label,target,action)=>{let button=B(label,action,true);button.className='quiet nav-button';if(page===target)button.setAttribute?.('aria-current','page');bar.append(button)};add('Perfiles','profiles',()=>{page='profiles';render()});if(activeProfile){add('Metas','home',()=>{page='home';render()});add('Aprendizaje','learning',()=>{page='learning';render()});add('Preferencias','preferences',()=>{page='preferences';render()})}if(g())add('Ruta y mapa','dashboard',()=>{page='dashboard';render()});if(persistenceDirty){let retry=B('Reintentar guardado',()=>task('Guardando…',save),true);retry.className='quiet nav-button';bar.append(retry)}app.append(bar);if(activeProfile){let strip=E('div'),goal=g(),state=E('span',persistenceDirty?'Cambios sin confirmar':pendingWrites?'Guardando…':'Sincronizado');strip.className='context-strip';state.className='status-pill '+(persistenceDirty?'bad':pendingWrites?'warn':'good');strip.append(E('strong',goal?.goal||'Sin meta activa'),E('span','Perfil: '+activeProfile.name),state);app.append(strip)}}
