 let reviews=(Array.isArray(raw.reviews)?raw.reviews:[]).filter(x=>x&&x.id).map(r=>{let invalidTemporal=['origin_at','last_exposure_at','scheduled_at','presented_at','answered_at'].some(key=>r[key]!==undefined&&r[key]!==null&&!finitePastTimestamp(r[key]));return {...r,step:Number.isFinite(r.step)?r.step:0,history:Array.isArray(r.history)?r.history.map(h=>({...h})):[],question:r.question&&typeof r.question==='object'?{...r.question}:null,target_dimension:Object.prototype.hasOwnProperty.call(REVIEW_ACTIVITY_KINDS,r.target_dimension)?r.target_dimension:null,origin_attempt_id:typeof r.origin_attempt_id==='string'&&r.origin_attempt_id?r.origin_attempt_id:null,origin_at:finitePastTimestamp(r.origin_at)?r.origin_at:null,last_exposure_at:finitePastTimestamp(r.last_exposure_at)?r.last_exposure_at:null,scheduled_at:finitePastTimestamp(r.scheduled_at)?r.scheduled_at:null,presented_at:finitePastTimestamp(r.presented_at)?r.presented_at:null,answered_at:finitePastTimestamp(r.answered_at)?r.answered_at:null,temporal_invalid:r.temporal_invalid===true||invalidTemporal,temporal_policy_version:r.temporal_policy_version||TEMPORAL_POLICY_VERSION}});
 let lessons={};for(let [id,value] of Object.entries(raw.lessons&&typeof raw.lessons==='object'?raw.lessons:{})){let l=value&&typeof value==='object'?value:{};lessons[id]={...l};for(let key of ['check','guided','independent','integration'])lessons[id][key]=l[key]&&typeof l[key]==='object'?{...l[key]}:null}
 let session=raw.session&&typeof raw.session==='object'?{...raw.session}:{mode:'DIAGNOSTIC',node:null,stack:[],stage:'teach',tries:0};session.mode=session.mode||'DIAGNOSTIC';session.node=session.node||null;session.stack=Array.isArray(session.stack)?[...session.stack]:[];session.tries=Number.isFinite(session.tries)?session.tries:0;session.hints=Number.isFinite(session.hints)?session.hints:0;
 let repairEpisodes=(Array.isArray(raw.repairEpisodes)?raw.repairEpisodes:[]).filter(x=>x&&x.episode_id).map(normalizeRepairEpisode),pendingRepairDiagnosis=normalizePendingRepairDiagnosis(raw.pending_repair_diagnosis);
