 let normalized={...raw,nodes,coverage,learner,reviews,events:Array.isArray(raw.events)?raw.events.map(e=>({...e})):[],lessons,session,map_updates:Array.isArray(raw.map_updates)?[...raw.map_updates]:[],contextStack:Array.isArray(raw.contextStack)?raw.contextStack.map(x=>({...x,history:Array.isArray(x.history)?x.history.map(h=>({...h})):[]})):[],repairEpisodes,pending_repair_diagnosis:pendingRepairDiagnosis,criterion_draft};return reconcileGoalRepairEpisodes(normalized)
