function reconcileGoalRepairEpisodes(goal){for(let episode of goal.repairEpisodes||[]){let parent=(goal.events||[]).find(event=>event&&event.type==='EVIDENCE'&&event.attempt_id===episode.parent_attempt_id&&event.activity_id===episode.parent_activity_id&&event.node_id===episode.parent_node_id),validParent=parent&&isLearningFailure(parent),checkpoint=episode.attempt_checkpoint,applied=checkpoint&&(goal.events||[]).find(event=>event&&event.type==='EVIDENCE'&&event.attempt_id===checkpoint.attempt_id);if(applied){checkpoint.status='APPLIED';checkpoint.applied_at=checkpoint.applied_at||applied.timestamp||applied.at||null}else if(checkpoint?.status==='APPLYING')checkpoint.status='EVALUATED';if(!validParent&&!['PARTIAL','FAILED','ABANDONED'].includes(episode.status)){episode.status='PARTIAL';episode.close_reason=episode.close_reason||'El episodio importado no conserva el fallo original del problema padre.'}}let pending=goal.pending_repair_diagnosis;if(pending){let parent=(goal.events||[]).find(event=>event&&event.type==='EVIDENCE'&&event.attempt_id===pending.parent_attempt_id&&event.activity_id===pending.parent_activity_id&&event.node_id===pending.parent_node_id);if(!parent||!isLearningFailure(parent))goal.pending_repair_diagnosis=null}return goal}
async function selectProfile(profileId){await flushSave();if(persistenceDirty)throw Error('Guarda o recarga el perfil actual antes de cambiar de perfil.');let loaded=await api('/api/profile/load',{profile_id:profileId});activeProfile={profile_id:loaded.profile_id,name:loaded.name,preferences:loaded.preferences};revision=loaded.revision;store=normalizeImportedStore(loaded.store);try{localStorage.setItem(PROFILE_KEY,profileId)}catch{}persistenceDirty=false;page='home';render();return loaded}
async function profilesView(){app.replaceChildren();let box=block('Perfiles locales');box.append(E('p','Cada perfil mantiene metas, sesiones e intentos separados en este equipo. No es una cuenta ni un control de acceso.'));let data;try{data=await api('/api/profiles/list',{})}catch(e){box.append(E('p','No se pudieron leer los perfiles: '+e.message));return}for(let profile of data.profiles||[])box.append(B((activeProfile?.profile_id===profile.profile_id?'✓ ':'')+profile.name,()=>task('Cargando memoria durable…',()=>selectProfile(profile.profile_id))),E('br'));let name=E('input');name.placeholder='Nombre del perfil local';box.append(name,B('Crear perfil',()=>task('Creando perfil local…',async()=>{let created=await api('/api/profile/create',{name:name.value});await selectProfile(created.profile_id)})));if(activeProfile)box.append(B('Volver a mis metas',()=>{page='home';render()},true))}
