  const events=effectiveEvidence(d.evidence||[]).filter(e=>e.evidence_scope!=='repair_episode'),successes=independentSuccesses(d),last=events.filter(e=>resultStatus(e.result??e.status)!=='UNKNOWN').at(-1),enough=sufficient(d);
